#!/usr/bin/env python3
import argparse
import copy
import json
import os
import re
import sys
import tempfile

import yaml

STORE_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "store.json")

NAME_RE = re.compile(r"^[a-z0-9][a-z0-9-]*[a-z0-9]$")
RUNTIME_RE = re.compile(r"^\d+\.\d+\.\d+$")
MEMORY_UNITS = {"Ki": 1024, "Mi": 1024**2, "Gi": 1024**3, "Ti": 1024**4}


# --- Output helpers ---

def print_json(obj):
    print(json.dumps(obj))


def make_error(field, type_, message):
    return {"field": field, "type": type_, "message": message}


def error_out(errors):
    print_json({"errors": errors})


# --- Store ---

def load_store():
    if not os.path.exists(STORE_PATH):
        return {}
    with open(STORE_PATH) as f:
        return json.load(f)


def save_store(store):
    dir_ = os.path.dirname(STORE_PATH)
    fd, tmp = tempfile.mkstemp(dir=dir_)
    try:
        with os.fdopen(fd, "w") as f:
            json.dump(store, f)
        os.replace(tmp, STORE_PATH)
    except Exception:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise


# --- YAML loader ---

def load_yaml_file(path):
    try:
        with open(path) as f:
            doc = yaml.safe_load(f)
    except FileNotFoundError:
        return None, [make_error("", "parse", f"file not found: {path}")]
    except yaml.YAMLError as e:
        return None, [make_error("", "parse", f"YAML parse error: {e}")]
    except OSError as e:
        return None, [make_error("", "parse", f"cannot read file: {e}")]

    if not isinstance(doc, dict):
        return None, [make_error("", "parse", "document must be a YAML mapping")]

    return doc, []


# --- Quantity parsers ---

def parse_memory_quantity(value):
    if not isinstance(value, str):
        return None
    for suffix, mult in MEMORY_UNITS.items():
        if value.endswith(suffix):
            num = value[: -len(suffix)]
            return int(num) * mult if re.fullmatch(r"\d+", num) else None
    return int(value) if re.fullmatch(r"\d+", value) else None


def parse_cpu_quantity(value):
    if not isinstance(value, str):
        return None
    if value.endswith("m"):
        num = value[:-1]
        return int(num) if re.fullmatch(r"\d+", num) else None
    return int(value) * 1000 if re.fullmatch(r"\d+", value) else None


# --- autoScaling scanner ---

def find_autoscaling_paths(obj, path):
    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            child = f"{path}.{k}" if path else k
            if k == "autoScaling":
                results.append(child)
            else:
                results.extend(find_autoscaling_paths(v, child))
    return results


# --- Conditions helpers ---

def set_condition(conditions, type_, status, message):
    conditions[:] = [c for c in conditions if c["type"] != type_]
    conditions.append({"type": type_, "status": status, "message": message})
    conditions.sort(key=lambda c: c["type"])


def clear_condition(conditions, type_):
    conditions[:] = [c for c in conditions if c["type"] != type_]


def compute_stable(conditions):
    transient = {"Scaling", "GracefulShutdown"}
    return not any(c["type"] in transient for c in conditions)


# --- Replication factor default ---

def default_replication_factor(instances):
    return min(3, instances)


# --- Deep merge ---

def deep_merge(base, override):
    result = dict(base)
    for k, v in override.items():
        if k in result and isinstance(result[k], dict) and isinstance(v, dict):
            result[k] = deep_merge(result[k], v)
        else:
            result[k] = v
    return result


# --- Storage output rule ---

def storage_for_output(storage):
    out = {"ephemeral": storage["ephemeral"]}
    if not storage["ephemeral"]:
        out["size"] = storage["size"]
    if "className" in storage:
        out["className"] = storage["className"]
    return out


# --- Resource output (applies storage rules) ---

def resource_output(resource):
    out = copy.deepcopy(resource)
    network = out["spec"].get("network")
    if isinstance(network, dict) and "storage" in network:
        network["storage"] = storage_for_output(network["storage"])
    return out


# --- Spec validation and normalization ---

def validate_spec(doc, is_update=False):
    """
    Validate and normalize. Returns (name, norm_spec, errors).
    is_update=True: instances=0 is allowed.
    """
    errors = []

    if "metadata" not in doc or "spec" not in doc:
        return None, None, [make_error("", "parse", "document must have 'metadata' and 'spec' keys")]

    metadata = doc["metadata"]
    spec = doc["spec"]

    if not isinstance(metadata, dict):
        metadata = {}
    if not isinstance(spec, dict):
        spec = {}

    # metadata.name
    name = None
    raw_name = metadata.get("name")
    if raw_name is None or raw_name == "":
        errors.append(make_error("metadata.name", "required", "name is required and must not be empty"))
    elif not isinstance(raw_name, str):
        errors.append(make_error("metadata.name", "required", "name must be a non-empty string"))
    elif not NAME_RE.match(raw_name):
        errors.append(make_error(
            "metadata.name", "invalid",
            "name must be lowercase alphanumeric with interior hyphens only, minimum 2 characters",
        ))
    else:
        name = raw_name

    # forbidden autoScaling
    for fp in find_autoscaling_paths(spec, "spec"):
        errors.append(make_error(fp, "forbidden", f"field '{fp}' is not allowed"))

    # spec.instances
    instances = None
    raw_instances = spec.get("instances")
    if raw_instances is None:
        instances = None if is_update else 1
    else:
        min_val = 0 if is_update else 1
        if isinstance(raw_instances, bool) or not isinstance(raw_instances, int) or raw_instances < min_val:
            msg = "instances must be a non-negative integer" if is_update else "instances must be a positive integer"
            errors.append(make_error("spec.instances", "invalid", msg))
        else:
            instances = raw_instances

    # spec.runtime
    runtime = None
    has_runtime = "runtime" in spec
    if has_runtime:
        raw_runtime = spec["runtime"]
        if not isinstance(raw_runtime, str) or not RUNTIME_RE.match(raw_runtime):
            errors.append(make_error(
                "spec.runtime", "invalid",
                "runtime must be in major.minor.patch format with non-negative integers",
            ))
        else:
            runtime = raw_runtime

    # spec.resources.memory
    raw_resources = spec.get("resources")
    has_resources = isinstance(raw_resources, dict)

    has_memory = has_resources and "memory" in raw_resources
    memory = None
    if not has_memory:
        memory = {"limit": "1Gi", "request": "1Gi"}
    else:
        raw_memory = raw_resources["memory"]
        if not isinstance(raw_memory, dict):
            errors.append(make_error("spec.resources.memory.limit", "required", "memory.limit is required"))
        else:
            mem_limit_str = raw_memory.get("limit")
            mem_req_str = raw_memory.get("request")
            if mem_limit_str is None:
                errors.append(make_error("spec.resources.memory.limit", "required", "memory.limit is required"))
            else:
                if not isinstance(mem_limit_str, str):
                    mem_limit_str = str(mem_limit_str)
                mem_limit_val = parse_memory_quantity(mem_limit_str)
                if mem_limit_val is None:
                    errors.append(make_error(
                        "spec.resources.memory.limit", "invalid",
                        f"invalid memory quantity: {mem_limit_str!r}",
                    ))
                else:
                    if mem_req_str is None:
                        mem_req_str = mem_limit_str
                        mem_req_val = mem_limit_val
                    else:
                        if not isinstance(mem_req_str, str):
                            mem_req_str = str(mem_req_str)
                        mem_req_val = parse_memory_quantity(mem_req_str)
                        if mem_req_val is None:
                            errors.append(make_error(
                                "spec.resources.memory.request", "invalid",
                                f"invalid memory quantity: {mem_req_str!r}",
                            ))
                            mem_req_val = None
                        elif mem_req_val > mem_limit_val:
                            errors.append(make_error(
                                "spec.resources.memory.request", "invalid",
                                "memory request must not exceed limit",
                            ))
                            mem_req_val = None
                    if mem_req_val is not None:
                        memory = {"limit": mem_limit_str, "request": mem_req_str}

    # spec.resources.cpu
    has_cpu = has_resources and "cpu" in raw_resources
    cpu = None
    if has_cpu:
        raw_cpu = raw_resources["cpu"]
        if not isinstance(raw_cpu, dict):
            errors.append(make_error("spec.resources.cpu.limit", "required", "cpu.limit is required"))
        else:
            cpu_limit_str = raw_cpu.get("limit")
            cpu_req_str = raw_cpu.get("request")
            if cpu_limit_str is None:
                errors.append(make_error("spec.resources.cpu.limit", "required", "cpu.limit is required"))
            else:
                if not isinstance(cpu_limit_str, str):
                    cpu_limit_str = str(cpu_limit_str)
                cpu_limit_val = parse_cpu_quantity(cpu_limit_str)
                if cpu_limit_val is None:
                    errors.append(make_error(
                        "spec.resources.cpu.limit", "invalid",
                        f"invalid CPU quantity: {cpu_limit_str!r}",
                    ))
                else:
                    if cpu_req_str is None:
                        cpu_req_str = cpu_limit_str
                        cpu_req_val = cpu_limit_val
                    else:
                        if not isinstance(cpu_req_str, str):
                            cpu_req_str = str(cpu_req_str)
                        cpu_req_val = parse_cpu_quantity(cpu_req_str)
                        if cpu_req_val is None:
                            errors.append(make_error(
                                "spec.resources.cpu.request", "invalid",
                                f"invalid CPU quantity: {cpu_req_str!r}",
                            ))
                            cpu_req_val = None
                        elif cpu_req_val > cpu_limit_val:
                            errors.append(make_error(
                                "spec.resources.cpu.request", "invalid",
                                "CPU request must not exceed limit",
                            ))
                            cpu_req_val = None
                    if cpu_req_val is not None:
                        cpu = {"limit": cpu_limit_str, "request": cpu_req_str}

    # spec.access.authentication.enabled
    raw_access = spec.get("access")
    raw_auth = raw_access.get("authentication") if isinstance(raw_access, dict) else None
    auth_enabled = True
    if isinstance(raw_auth, dict) and "enabled" in raw_auth:
        auth_enabled = raw_auth["enabled"]

    # spec.migration.strategy
    strategy = "FullStop"
    raw_migration = spec.get("migration")
    if isinstance(raw_migration, dict) and "strategy" in raw_migration:
        raw_strategy = raw_migration["strategy"]
        if raw_strategy != "FullStop":
            errors.append(make_error(
                "spec.migration.strategy", "invalid",
                f"migration.strategy must be 'FullStop', got {raw_strategy!r}",
            ))
            strategy = None

    # spec.network.storage
    raw_network = spec.get("network")
    raw_storage = raw_network.get("storage") if isinstance(raw_network, dict) else None

    storage_size = "1Gi"
    storage_ephemeral = False
    storage_class_name = None
    has_class_name = False

    if isinstance(raw_storage, dict):
        if "size" in raw_storage:
            sz = raw_storage["size"]
            if not isinstance(sz, str):
                sz = str(sz)
            if parse_memory_quantity(sz) is None:
                errors.append(make_error("spec.network.storage.size", "invalid", f"invalid memory quantity: {sz!r}"))
            else:
                storage_size = sz

        if "ephemeral" in raw_storage:
            ep = raw_storage["ephemeral"]
            if not isinstance(ep, bool):
                errors.append(make_error("spec.network.storage.ephemeral", "invalid", "ephemeral must be a boolean"))
            else:
                storage_ephemeral = ep

        if "className" in raw_storage:
            cn = raw_storage["className"]
            if not isinstance(cn, str):
                errors.append(make_error("spec.network.storage.className", "invalid", "className must be a string"))
            else:
                storage_class_name = cn
                has_class_name = True

    # spec.network.replicationFactor
    replication_factor = None
    if isinstance(raw_network, dict) and "replicationFactor" in raw_network:
        raw_rf = raw_network["replicationFactor"]
        if isinstance(raw_rf, bool) or not isinstance(raw_rf, int) or raw_rf < 1:
            errors.append(make_error(
                "spec.network.replicationFactor", "invalid",
                "replicationFactor must be a positive integer (>= 1)",
            ))
        else:
            replication_factor = raw_rf

    # Post-merge constraint: replicationFactor <= instances (skip when instances=0/stopped)
    if instances is not None and instances > 0 and replication_factor is not None:
        if replication_factor > instances:
            errors.append(make_error(
                "spec.network.replicationFactor", "invalid",
                f"replicationFactor {replication_factor} exceeds instance count {instances}",
            ))
            replication_factor = None

    if errors:
        return None, None, errors

    # Apply replicationFactor default
    if replication_factor is None:
        replication_factor = default_replication_factor(instances) if instances and instances > 0 else 1

    storage = {"size": storage_size, "ephemeral": storage_ephemeral}
    if has_class_name:
        storage["className"] = storage_class_name

    norm_spec = {
        "instances": instances if instances is not None else 1,
        "resources": {"memory": memory},
        "access": {"authentication": {"enabled": auth_enabled}},
        "migration": {"strategy": strategy},
        "network": {
            "storage": storage,
            "replicationFactor": replication_factor,
        },
    }
    if has_runtime:
        norm_spec["runtime"] = runtime
    if has_cpu:
        norm_spec["resources"]["cpu"] = cpu

    return name, norm_spec, []


# --- Command handlers ---

def cmd_create(args):
    doc, errs = load_yaml_file(args.file)
    if errs:
        error_out(errs)
        return

    name, norm_spec, errs = validate_spec(doc, is_update=False)
    if errs:
        error_out(errs)
        return

    store = load_store()
    if name in store:
        error_out([make_error("metadata.name", "duplicate", f"mesh '{name}' already exists")])
        return

    instances = norm_spec["instances"]
    conditions = [
        {"type": "Healthy", "status": "True", "message": ""},
        {"type": "PrechecksPassed", "status": "True", "message": ""},
    ]
    status = {
        "state": "Running" if instances > 0 else "Stopped",
        "stable": True,
        "instances": {"ready": instances, "starting": 0, "stopped": 0},
        "conditions": conditions,
    }

    resource = {"metadata": {"name": name}, "spec": norm_spec, "status": status}
    store[name] = resource
    save_store(store)
    print_json(resource_output(resource))


def cmd_list(_args):
    store = load_store()
    items = sorted(
        [{"name": r["metadata"]["name"], "status": {"state": r["status"]["state"]}} for r in store.values()],
        key=lambda x: x["name"],
    )
    print_json(items)


def cmd_describe(args):
    store = load_store()
    if args.name not in store:
        error_out([make_error("metadata.name", "not_found", f"mesh '{args.name}' not found")])
        return
    print_json(resource_output(store[args.name]))


def cmd_delete(args):
    store = load_store()
    name = args.name
    if name not in store:
        error_out([make_error("metadata.name", "not_found", f"mesh '{name}' not found")])
        return
    del store[name]
    save_store(store)
    print_json({"message": f"mesh '{name}' deleted", "metadata": {"name": name}})


def cmd_update(args):
    doc, errs = load_yaml_file(args.file)
    if errs:
        error_out(errs)
        return

    incoming_meta = doc.get("metadata") if isinstance(doc.get("metadata"), dict) else {}
    incoming_spec = doc.get("spec") if isinstance(doc.get("spec"), dict) else {}

    # Look up mesh by name before full validation
    raw_name = incoming_meta.get("name") if isinstance(incoming_meta, dict) else None
    if not raw_name:
        error_out([make_error("metadata.name", "required", "name is required and must not be empty")])
        return

    store = load_store()
    if raw_name not in store:
        error_out([make_error("metadata.name", "not_found", f"mesh '{raw_name}' not found")])
        return

    stored = store[raw_name]
    stored_spec = stored["spec"]
    stored_status = stored["status"]
    stored_conditions = [dict(c) for c in stored_status.get("conditions", [])]

    # Immutable field check: spec.network.storage.size
    incoming_network = incoming_spec.get("network") if isinstance(incoming_spec, dict) else None
    incoming_storage = incoming_network.get("storage") if isinstance(incoming_network, dict) else None
    if isinstance(incoming_storage, dict) and "size" in incoming_storage:
        stored_size = stored_spec.get("network", {}).get("storage", {}).get("size", "1Gi")
        incoming_size = incoming_storage["size"]
        if not isinstance(incoming_size, str):
            incoming_size = str(incoming_size)
        if incoming_size != stored_size:
            error_out([make_error(
                "spec.network.storage.size", "immutable",
                "field 'spec.network.storage.size' is immutable after creation",
            )])
            return

    has_graceful_shutdown = any(c["type"] == "GracefulShutdown" for c in stored_conditions)
    incoming_instances_explicit = isinstance(incoming_spec, dict) and "instances" in incoming_spec

    # Deep merge incoming over stored
    merged_spec = deep_merge(stored_spec, incoming_spec if isinstance(incoming_spec, dict) else {})

    # Resume with omitted instances: use desiredInstancesOnResume as target
    if has_graceful_shutdown and not incoming_instances_explicit:
        desired = stored_status.get("desiredInstancesOnResume")
        if desired is not None:
            merged_spec = {**merged_spec, "instances": desired}

    merged_doc = {"metadata": incoming_meta, "spec": merged_spec}

    name, norm_spec, errs = validate_spec(merged_doc, is_update=True)
    if errs:
        error_out(errs)
        return

    old_instances = stored_spec.get("instances", 1)
    new_instances = norm_spec["instances"]

    # Build condition lists for response (transient) and settled state
    response_conditions = [dict(c) for c in stored_conditions]
    settled_conditions = [dict(c) for c in stored_conditions]

    if has_graceful_shutdown and new_instances > 0:
        # Resume
        clear_condition(response_conditions, "GracefulShutdown")
        clear_condition(settled_conditions, "GracefulShutdown")

        response_status = {
            "state": "Running",
            "stable": compute_stable(response_conditions),
            "instances": {"ready": 0, "starting": new_instances, "stopped": 0},
            "conditions": response_conditions,
        }
        settled_status = {
            "state": "Running",
            "stable": compute_stable(settled_conditions),
            "instances": {"ready": new_instances, "starting": 0, "stopped": 0},
            "conditions": settled_conditions,
        }

    elif new_instances == 0 and old_instances > 0 and not has_graceful_shutdown:
        # Stop
        set_condition(response_conditions, "GracefulShutdown", "True", "")
        set_condition(settled_conditions, "GracefulShutdown", "True", "")

        response_status = {
            "state": "Stopped",
            "stable": compute_stable(response_conditions),
            "instances": {"ready": 0, "starting": 0, "stopped": old_instances},
            "conditions": response_conditions,
            "desiredInstancesOnResume": old_instances,
        }
        settled_status = {
            "state": "Stopped",
            "stable": compute_stable(settled_conditions),
            "instances": {"ready": 0, "starting": 0, "stopped": old_instances},
            "conditions": settled_conditions,
            "desiredInstancesOnResume": old_instances,
        }

    elif new_instances > old_instances and old_instances > 0 and not has_graceful_shutdown:
        # Scale up
        msg = f"Scaling from {old_instances} to {new_instances} instances"
        set_condition(response_conditions, "Scaling", "True", msg)

        response_status = {
            "state": "Running",
            "stable": False,
            "instances": {"ready": old_instances, "starting": new_instances - old_instances, "stopped": 0},
            "conditions": response_conditions,
        }
        # settled: Scaling is transient, not stored
        settled_status = {
            "state": "Running",
            "stable": compute_stable(settled_conditions),
            "instances": {"ready": new_instances, "starting": 0, "stopped": 0},
            "conditions": settled_conditions,
        }

    elif 0 < new_instances < old_instances and not has_graceful_shutdown:
        # Scale down
        msg = f"Scaling from {old_instances} to {new_instances} instances"
        set_condition(response_conditions, "Scaling", "True", msg)

        response_status = {
            "state": "Running",
            "stable": False,
            "instances": {"ready": old_instances, "starting": 0, "stopped": 0},
            "conditions": response_conditions,
        }
        settled_status = {
            "state": "Running",
            "stable": compute_stable(settled_conditions),
            "instances": {"ready": new_instances, "starting": 0, "stopped": 0},
            "conditions": settled_conditions,
        }

    else:
        # No lifecycle change — preserve existing instance counts
        state = "Running" if new_instances > 0 else "Stopped"
        current_inst = dict(stored_status.get("instances", {"ready": old_instances, "starting": 0, "stopped": 0}))

        response_status = {
            "state": state,
            "stable": compute_stable(settled_conditions),
            "instances": current_inst,
            "conditions": settled_conditions,
        }
        if "desiredInstancesOnResume" in stored_status:
            response_status["desiredInstancesOnResume"] = stored_status["desiredInstancesOnResume"]
        settled_status = response_status

    # Save settled state
    settled_resource = {"metadata": {"name": name}, "spec": norm_spec, "status": settled_status}
    store[name] = settled_resource
    save_store(store)

    # Emit response (may have transient conditions not in store)
    response_resource = {"metadata": {"name": name}, "spec": norm_spec, "status": response_status}
    print_json(resource_output(response_resource))


# --- CLI entry point ---

def main():
    parser = argparse.ArgumentParser(prog="meshctl")
    top_sub = parser.add_subparsers(dest="command")

    mesh_p = top_sub.add_parser("mesh")
    mesh_sub = mesh_p.add_subparsers(dest="operation")

    create_p = mesh_sub.add_parser("create")
    create_p.add_argument("-f", dest="file", required=True)

    mesh_sub.add_parser("list")

    describe_p = mesh_sub.add_parser("describe")
    describe_p.add_argument("name")

    delete_p = mesh_sub.add_parser("delete")
    delete_p.add_argument("name")

    update_p = mesh_sub.add_parser("update")
    update_p.add_argument("-f", dest="file", required=True)

    args = parser.parse_args()

    if args.command != "mesh" or not args.operation:
        parser.print_usage(sys.stderr)
        sys.exit(1)

    {
        "create": cmd_create,
        "list": cmd_list,
        "describe": cmd_describe,
        "delete": cmd_delete,
        "update": cmd_update,
    }[args.operation](args)


if __name__ == "__main__":
    main()

